    runs = []
    for r, row in enumerate(grid):
        c = 0
        while c < len(row):
            val = row[c]
            run_end = c + 1
            while run_end < len(row) and row[run_end] == val:
                run_end += 1
            if run_end - c >= 3:
                runs.append((r, c, run_end-1, val))
            c = run_end
    return runs

